    ('METAL_DECK', 'Metal Deck', 'Metal Deck', '05 31 00', 'D-18', '2', '7'),
    ('SLAB_ON_GRADE', 'Slab on Grade', 'Slab on Grade', '03 30 00', 'D-07', '3', '8'),
    ('SLAB_ON_DECK', 'Slab on Deck', 'Slab on Deck', '03 30 00', 'D-07', '3', '9'),
