    ('DRYWALL_FRAMING', 'Drywall Framing', 'Drywall Framing', '09 22 00', 'D-18', '2', '11'),
    ('DRYWALL_BOARD', 'Drywall Board', 'Drywall Board', '09 29 00', 'D-20', '2', '12'),
