-- qc_seed_Gate: 93 row(s) from seed/qc_gate_template.csv
CREATE OR REPLACE TABLE qc_seed_Gate AS
SELECT CAST(c1 AS STRING) AS GateType,
       CAST(c2 AS STRING) AS GateKey,
       CAST(c3 AS STRING) AS Step,
