-- qc_seed_DohItem: 101 row(s) from seed/qc_doh_items.csv
CREATE OR REPLACE TABLE qc_seed_DohItem AS
SELECT CAST(c1 AS STRING) AS ItemKey,
       CAST(c2 AS STRING) AS Section,
       CAST(c3 AS STRING) AS Requirement,
       CAST(c4 AS STRING) AS Responsibility,
       CAST(c5 AS STRING) AS AffectInterface,
       CAST(c6 AS STRING) AS EvidenceRequired,
       CAST(c7 AS STRING) AS Reference,
       CAST(c8 AS INT) AS SortOrder
FROM (VALUES
    ('H-01', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'Pool / spa construction plans submitted to and approved by DOHMH before construction of the pool shell', 'Owner / DOH Consultant', 'AB must not build out enclosing finishes until plan approval is confirmed', 'Stamped approved DOH plan set', 'NYC Health Code Art. 165 / NYS Subpart 6-1', '1'),
    ('H-02', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'Confirm whether the facility is classified as a swimming pool, spa, or both — classification drives the applicable requirements', 'Owner / DOH Consultant', 'Drives ventilation, drainage and finish requirements in AB scope', 'Written DOH classification determination', 'Subpart 6-1 definitions', '2'),
    ('H-03', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'DOH Permit to Operate application filed; permit issued prior to public use', 'Owner / DOH Consultant', 'Prerequisite to TCO for pool / sauna areas (CMP §20.3)', 'Issued DOH Permit to Operate', 'Art. 165', '3'),
    ('H-04', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'Food Service Establishment permit application for kitchen and bar filed with DOHMH', 'Owner / DOH Consultant', 'AB builds out kitchen / bar to DOH-acceptable finishes and equipment rough-in', 'FSE permit application + issued permit', 'NYC Health Code Art. 81', '4'),
    ('H-05', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'Food service plan review / pre-permit inspection scheduled with DOHMH', 'Owner / DOH Consultant', 'AB coordinates access and completion sequencing', 'Plan review approval letter', 'Art. 81', '5'),
    ('H-06', 'PERMITS, PLAN APPROVAL & ADMINISTRATION', 'Owner''s DOH consultant engaged and scope of responsibility documented in writing', 'Owner / DOH Consultant', 'Clarifies the boundary between AB scope and Owner''s vendors', 'Consultant agreement / scope letter', 'Contract §12.4', '6'),
