-- dim_QcStatus: 141 row(s) from seed/qc_status_vocab.csv
CREATE OR REPLACE TABLE dim_QcStatus AS
SELECT CAST(c1 AS STRING) AS Domain,
       CAST(c2 AS STRING) AS Code,
       CAST(c3 AS STRING) AS Label,
       CAST(c4 AS INT) AS SortOrder,
       CAST(c5 AS BOOLEAN) AS IsTerminal,
